5|use Closure;
6|use Illuminate\Http\Request;
7|use Symfony\Component\HttpFoundation\Response;
8|
9|class ValidateUnitContext
10|{
11|    public function handle(Request $request, Closure $next): Response
12|    {
13|        $user = $request->user();
14|
15|        if (! $user) {
16|            return $next($request);
17|        }
18|
19|        $currentUnitId = session('current_unit_id');
20|
21|        if ($currentUnitId) {
22|            $hasAccess = $user->units()->where('units.id', $currentUnitId)->exists();
23|
24|            if ($hasAccess) {
25|                return $next($request);
26|            }
27|
28|            session()->forget('current_unit_id');
29|            session()->forget('current_unit_name');
30|            $currentUnitId = null;
31|        }
32|
33|        // Only load units relationship when current_unit_id is not set
34|        $userUnits = $user->units;
35|
36|        if ($userUnits->isEmpty()) {
37|            $person = $user->person;
38|            if ($person?->u_id) {
39|                session(['current_unit_id' => $person->u_id]);
40|                session(['current_unit_name' => $person->unit?->name ?? '-']);
41|            }
42|
43|            return $next($request);
44|        }
45|
46|        if ($userUnits->count() === 1) {
47|            $unit = $userUnits->first();
48|            session(['current_unit_id' => $unit->id]);
49|            session(['current_unit_name' => $unit->name]);
50|
51|            return $next($request);
52|        }
53|
54|        return redirect('/select-context');
55|    }
