9|
10|return new class extends Component
11|{
12|    public string $dateFrom = '';
13|
14|    public string $dateTo = '';
15|
16|    public ?int $selectedUnitId = null;
17|
18|    public ?string $statusFilter = null; // completed, pending, overdue, null=all
19|
20|    public $units = [];
21|
22|    public bool $showHelpModal = false;
23|
24|    public function mount(): void
25|    {
26|        $this->dateFrom = Jalalian::fromCarbon(now()->subDays(30))->format('Y/m/d');
27|        $this->dateTo = Jalalian::fromCarbon(now()->addDays(30))->format('Y/m/d');
28|        $this->units = \App\Models\Unit::all();
29|    }
30|
31|    private function parseJalaliDate(?string $date, bool $endOfDay = false): ?Carbon
32|    {
33|        if (empty($date)) {
34|            return null;
35|        }
36|        try {
37|            $carbon = Jalalian::fromFormat('Y/m/d', $date)->toCarbon();
38|
39|            return $endOfDay ? $carbon->endOfDay() : $carbon->startOfDay();
40|        } catch (\Throwable) {
41|            return null;
42|        }
43|    }
44|
45|    /**
46|     * The chosen from..to range as Carbon bounds, or null when either end is
47|     * missing/invalid — in which case the daily series has no window to fill.
48|     *
49|     * @return array{0: Carbon, 1: Carbon}|null
50|     */
51|    private function dateRange(): ?array
52|    {
53|        $from = $this->parseJalaliDate($this->dateFrom);
54|        $to = $this->parseJalaliDate($this->dateTo, endOfDay: true);
55|
56|        if (! $from || ! $to || $from->gt($to)) {
57|            return null;
58|        }
59|
60|        return [$from, $to];
61|    }
62|
63|    public function chartPayload(): array
64|    {
65|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
66|
67|        $query = Todo::query()
68|            ->when($accessibleIds, fn ($q) => $q->whereIn('unit_id', $accessibleIds))
69|            ->when($this->selectedUnitId, fn ($q) => $q->where('unit_id', $this->selectedUnitId));
70|
71|        if ($from = $this->parseJalaliDate($this->dateFrom)) {
72|            $query->where('start_at', '>=', $from);
73|        }
74|        if ($to = $this->parseJalaliDate($this->dateTo, endOfDay: true)) {
75|            $query->where('end_at', '<=', $to);
76|        }
77|
78|        $now = now();
79|        $completed = (clone $query)->where('is_completed', true)->count();
80|        $pending = (clone $query)->where('is_completed', false)->count();
81|        $overdue = (clone $query)->where('is_completed', false)
82|            ->whereNotNull('end_at')->where('end_at', '<', $now)->count();
83|
84|        $byUnit = Todo::selectRaw('COALESCE(units.name, ?) as unit_name, COUNT(*) as count', ['نامشخص'])
85|            ->whereIn('todos.unit_id', $accessibleIds)
86|            ->when($this->selectedUnitId, fn ($q) => $q->where('todos.unit_id', $this->selectedUnitId))
87|            ->leftJoin('units', 'todos.unit_id', '=', 'units.id')
88|            ->groupBy('unit_name')
89|            ->pluck('count', 'unit_name')
90|            ->toArray();
91|
92|        // Issue #736: materialise every day in the chosen range, zeros included,
93|        // so a day with no todos is a zero rather than a missing column. The
94|        // filtered $query is reused, so unit/status/date filters still apply.
95|        $range = $this->dateRange();
96|        $byDay = $range
97|            ? array_map(
98|                fn (array $row) => [
99|                    'day' => Jalalian::fromCarbon(Carbon::parse($row['day']))->format('Y/m/d'),
100|                    'count' => $row['count'],
101|                ],
102|                DailySeries::between($range[0], $range[1])->counts(clone $query, 'start_at')
103|            )
104|            : [];
105|
106|        $byStatus = [
107|            'تکمیل شده' => $completed,
108|            'در انتظار' => $pending,
109|            'سررسید گذشته' => $overdue,
110|        ];
111|
112|        $items = (clone $query)
113|            ->when($this->statusFilter === 'completed', fn ($q) => $q->where('is_completed', true))
114|            ->when($this->statusFilter === 'pending', fn ($q) => $q->where('is_completed', false)->where(fn ($q) => $q->whereNull('end_at')->orWhere('end_at', '>=', $now)))
115|            ->when($this->statusFilter === 'overdue', fn ($q) => $q->where('is_completed', false)->whereNotNull('end_at')->where('end_at', '<', $now))
116|            ->with('unit:id,name')
117|            ->orderBy('start_at', 'desc')
118|            ->get()
119|            ->map(fn ($t) => [
120|                'id' => $t->id,
121|                'title' => $t->title,
122|                'unit' => $t->unit?->name ?? '—',
123|                'start' => $t->start_at ? Jalalian::fromCarbon(Carbon::parse($t->start_at))->format('Y/m/d') : '—',
124|                'end' => $t->end_at ? Jalalian::fromCarbon(Carbon::parse($t->end_at))->format('Y/m/d') : '—',
125|                'completed' => $t->is_completed,
126|                'is_overdue' => ! $t->is_completed && $t->end_at && $t->end_at < $now,
127|            ])
128|            ->toArray();
129|
130|        return [
131|            'completed' => $completed,
132|            'pending' => $pending,
133|            'overdue' => $overdue,
134|            'byUnit' => $byUnit,
135|            'byDay' => $byDay,
136|            'byStatus' => $byStatus,
137|            'items' => $items,
138|        ];
139|    }
