{"content": "1|<?php
2|
3|use App\Models\Person;
4|use App\Models\Ticket;
5|use App\Models\Todo;
6|use App\Models\Unit;
7|use App\Services\AccessService;
8|use App\Services\DailySeries;
9|use Carbon\Carbon;
10|use Illuminate\Support\Facades\Cache;
11|use Livewire\Attributes\Layout;
12|use Livewire\Component;
13|use Livewire\WithPagination;
14|use Morilog\Jalali\Jalalian;
15|
16|return new class extends Component
17|{
18|    use WithPagination;
19|
20|    public string $reportType = 'tickets';
21|
22|    public ?string $dateFrom = null;
23|
24|    public ?string $dateTo = null;
25|
26|    public ?int $unitId = null;
27|
28|    public ?int $parentUnitId = null;
29|
30|    public ?int $rootUnitId = null;
31|
32|    public string $statusFilter = 'all';
33|
34|    public $units = [];
35|
36|    public function mount(): void
37|    {
38|        $this->dateFrom = Jalalian::fromCarbon(now()->subDays(30))->format('Y/m/d');
39|        $this->dateTo = Jalalian::fromCarbon(now())->format('Y/m/d');
40|
41|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
42|        if (empty($accessibleIds)) {
43|            $this->units = [];
44|        } else {
45|            $cacheKey = 'advanced_report:units:'.md5(implode(',', $accessibleIds));
46|            $this->units = Cache::remember($cacheKey, 300, function () use ($accessibleIds) {
47|                return Unit::whereIn('id', $accessibleIds)
48|                    ->select('id', 'name', 'parent_id')
49|                    ->orderBy('name')
50|                    ->get()
51|                    ->toArray();
52|            });
53|        }
54|    }
55|
56|    private function parseJalaliDate(?string $date, bool $endOfDay = false): ?Carbon
57|    {
58|        if (empty($date)) {
59|            return null;
60|        }
61|
62|        try {
63|            $carbon = Jalalian::fromFormat('Y/m/d', $date)->toCarbon();
64|
65|            return $endOfDay ? $carbon->endOfDay() : $carbon->startOfDay();
66|        } catch (\Throwable) {
67|            return null;
68|        }
69|    }
70|
71|    /**
72|     * The chosen from..to range as Carbon bounds, or null when either end is
73|     * missing/invalid or the range is inverted — in which case the daily series
74|     * has no window to fill.
75|     *
76|     * @return array{0: Carbon, 1: Carbon}|null
77|     */
78|    private function dateRange(): ?array
79|    {
80|        $from = $this->parseJalaliDate($this->dateFrom);
81|        $to = $this->parseJalaliDate($this->dateTo, endOfDay: true);
82|
83|        if (! $from || ! $to || $from->gt($to)) {
84|            return null;
85|        }
86|
87|        return [$from, $to];
88|    }
89|
90|    #[Livewire\Attributes\Computed]
91|    public function childUnits()
92|    {
93|        if (! $this->rootUnitId || empty($this->units)) {
94|            return collect();
95|        }
96|
97|        return collect($this->units)->where('parent_id', $this->rootUnitId)->values();
98|    }
99|
100|    #[Livewire\Attributes\Computed]
101|    public function grandChildUnits()
102|    {
103|        if (! $this->parentUnitId || empty($this->units)) {
104|            return collect();
105|        }
106|
107|        return collect($this->units)->where('parent_id', $this->parentUnitId)->values();
108|    }
109|
110|    public function updatedRootUnitId(): void
111|    {
112|        $this->parentUnitId = null;
113|        $this->unitId = null;
114|    }
115|
116|    public function updatedParentUnitId(): void
117|    {
118|        $this->unitId = null;
119|    }
120|
121|    #[Livewire\Attributes\Computed]
122|    public function reportData(): array
123|    {
124|        $accessibleIds = app(AccessService::class)->accessibleUnitIds();
125|
126|        $query = match ($this->reportType) {
127|            'tickets' => Ticket::whereIn('unit_id', $accessibleIds),
128|            'todos' => Todo::whereIn('unit_id', $accessibleIds),
129|            'persons' => Person::whereIn('u_id', $accessibleIds),
130|            default => Ticket::whereIn('unit_id', $accessibleIds),
131|        };
132|
133|        // فیلتر تاریخ (ورودی شمسی)
134|        if ($from = $this->parseJalaliDate($this->dateFrom)) {
135|            $query->where('created_at', '>=', $from);
136|        }
137|        if ($to = $this->parseJalaliDate($this->dateTo, endOfDay: true)) {
138|            $query->where('created_at', '<=', $to);
139|        }
140|
141|        // فیلتر واحد (سلسله‌مراتبی)
142|        $unitId = $this->unitId ?? $this->parentUnitId ?? $this->rootUnitId;
143|        if ($unitId) {
144|            $descendantIds = Unit::descendantIds($unitId)->toArray();
145|            $descendantIds[] = $unitId;
146|            $unitColumn = $this->reportType === 'persons' ? 'u_id' : 'unit_id';
147|            $query->whereIn($unitColumn, $descendantIds);
148|        }
149|
150|        // فیلتر وضعیت
151|        if ($this->statusFilter !== 'all' && $this->reportType !== 'persons') {
152|            $query->where('status', $this->statusFilter);
153|        }
154|
155|        $total = $query->count();
156|
157|        // Issue #736: materialise every day in the chosen range, zeros included,
158|        // so a day with no rows is a zero rather than a missing column. The
159|        // filtered $query is reused, so unit/status/date filters still apply.
160|        $range = $this->dateRange();
161|        $byDay = $range
162|            ? array_map(
163|                fn (array $row) => [
164|                    'day' => Jalalian::fromCarbon(Carbon::parse($row['day']))->format('Y/m/d'),
165|                    'count' => $row['count'],
166|                ],
167|                DailySeries::between($range[0], $range[1])->counts($query->clone(), 'created_at')
168|            )
169|            : [];
170|
171|        $unitColumn = $this->reportType === 'persons' ? 'u_id' : 'unit_id';
172|        $byUnit = $query->clone()
173|            ->selectRaw("$unitColumn, count(*) as count")
174|            ->groupBy($unitColumn)
175|            ->with('unit:id,name')
176|            ->get()
177|            ->mapWithKeys(fn ($item) => [$item->unit?->name ?? 'نامشخص' => $item->count])
178|            ->toArray();
179|
180|        $details = [];
181|        if ($this->reportType === 'tickets') {
182|            $details = [
183|                'urgent' => (clone $query)->where('priority', 'urgent')->count(),
184|                'normal' => (clone $query)->where('priority', 'normal')->count(),
185|                'low' => (clone $query)->where('priority', 'low')->count(),
186|                'overdue' => (clone $query)
187|                    ->whereIn('status', ['created', 'forwarded'])
188|                    ->where('deadline', '<', now())
189|                    ->count(),
190|            ];
191|        } elseif ($this->reportType === 'persons') {
192|            $details = [
193|                'byEstekhdam' => Person::selectRaw('COALESCE(estekhdams.name, ?) as name, COUNT(*) as count', ['نامشخص'])
194|                    ->leftJoin('estekhdams', 'persons.e_id', '=', 'estekhdams.id')
195|                    ->when($accessibleIds, fn ($q) => $q->whereIn('persons.u_id', $accessibleIds))
196|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
197|                    ->groupBy('name')
198|                    ->pluck('count', 'name')
199|                    ->toArray(),
200|                'byTahsil' => Person::selectRaw('COALESCE(tahsils.name, ?) as name, COUNT(*) as count', ['نامشخص'])
201|                    ->leftJoin('tahsils', 'persons.t_id', '=', 'tahsils.id')
202|                    ->when($accessibleIds, fn ($q) => $q->whereIn('persons.u_id', $accessibleIds))
203|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
204|                    ->groupBy('name')
205|                    ->pluck('count', 'name')
206|                    ->toArray(),
207|                'bySemat' => Person::selectRaw('COALESCE(semats.name, ?) as name, COUNT(*) as count', ['نامشخص'])
208|                    ->leftJoin('semats', 'persons.s_id', '=', 'semats.id')
209|                    ->when($accessibleIds, fn ($q) => $q->whereIn('persons.u_id', $accessibleIds))
210|                    ->when($unitId, fn ($q) => $q->whereIn('persons.u_id', $descendantIds))
211|                    ->groupBy('name')
212|                    ->pluck('count', 'name')
213|                    ->toArray(),
214|            ];
215|        }
216|
217|        return [
218|            'total' => $total,
219|            'byDay' => $byDay,
220|            'byUnit' => $byUnit,
221|            'details' => $details,
222|        ];
223|    }
224|
225|    /**
226|     * Fresh chart data for JS (wire:navigate + filter updates).
227|     *
228|     * @return array{total: int, byDay: array, byUnit: array, details: array}
229|     */
230|    public function chartPayload(): array
231|    {
232|        return $this->reportData;
233|    }
234|}; ?>
